package com.cestasdamel.erp.service;
import com.cestasdamel.erp.dto.Requests.*; import com.cestasdamel.erp.dto.Responses.*; import com.cestasdamel.erp.exception.*; import com.cestasdamel.erp.model.*; import com.cestasdamel.erp.repository.*; import java.math.*; import java.time.Instant; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class OperationsService {
 private final SaleRepository sales; private final PurchaseRepository purchases; private final ExpenseRepository expenses; private final InventoryService inventory; private final FinanceService finance; private final UnitConversionService units; private final HistoryService history;
 @Transactional public SaleView sale(SaleInput r){Instant at=r.soldAt()==null?Instant.now():r.soldAt();Sale sale=new Sale();sale.setSoldAt(at);sale.setPaymentMethod(r.paymentMethod());sale.setObservations(r.observations());sale.setTotal(BigDecimal.ZERO);sales.save(sale);BigDecimal total=BigDecimal.ZERO;for(SaleLine line:r.items()){SaleItem item=createSaleItem(sale,line,at);sale.getItems().add(item);total=total.add(item.getSubtotal());}sale.setTotal(total);sales.save(sale);finance.create(Enums.TransactionType.INCOME,Enums.TransactionSource.SALE,sale.getId(),saleDescription(sale),total,at);return ViewMapper.sale(sale);}
 private String saleDescription(Sale sale){String items=sale.getItems().stream().map(item->item.getQuantity().stripTrailingZeros().toPlainString()+"x "+item.getItemName()).collect(java.util.stream.Collectors.joining(", "));String description="Venda #"+sale.getId()+" - "+items;return description.length()<=255?description:description.substring(0,252)+"...";}
 private SaleItem createSaleItem(Sale sale,SaleLine line,Instant at){SaleItem item=new SaleItem();item.setSale(sale);item.setItemType(line.type());item.setReferenceId(line.referenceId());item.setQuantity(line.quantity());BigDecimal price;if(line.type()==Enums.ItemType.PRODUCT){integer(line.quantity(),"Quantidade de produtos deve ser inteira");Product p=inventory.lockProduct(line.referenceId());active(p.isActive(),"Produto",p.getName());inventory.remove(p,line.quantity(),Enums.MovementReason.SALE,sale.getId(),"Venda do produto",at);item.setItemName(p.getName());price=line.unitPrice()==null?p.getSalePrice():line.unitPrice();}else if(line.type()==Enums.ItemType.BASKET){integer(line.quantity(),"Quantidade de cestas deve ser inteira");BasketTemplate b=inventory.lockBasket(line.referenceId());active(b.isActive(),"Cesta",b.getName());inventory.remove(b,line.quantity(),Enums.MovementReason.SALE,sale.getId(),"Venda de cesta pronta",at);item.setItemName(b.getName());price=line.unitPrice()==null?b.getSalePrice():line.unitPrice();}else throw new BusinessException("Venda aceita apenas produto ou cesta pronta");item.setUnitPrice(price);item.setSubtotal(price.multiply(line.quantity()));return item;}
 @Transactional public SaleView cancelSale(Long id,CancellationInput r){Sale sale=sales.lockDetailedById(id).orElseThrow(()->new NotFoundException("Venda",id));if(sale.getStatus()==Enums.SaleStatus.CANCELLED)throw new BusinessException("Venda já cancelada");Instant at=Instant.now();for(SaleItem item:sale.getItems()){if(item.getItemType()==Enums.ItemType.PRODUCT){Product p=inventory.lockProduct(item.getReferenceId());inventory.add(p,item.getQuantity(),Enums.MovementReason.CANCELLATION,sale.getId(),"Estorno da venda #"+sale.getId(),at);}else if(item.getItemType()==Enums.ItemType.BASKET){BasketTemplate b=inventory.lockBasket(item.getReferenceId());inventory.add(b,item.getQuantity(),Enums.MovementReason.CANCELLATION,sale.getId(),"Estorno da venda #"+sale.getId(),at);}}sale.setStatus(Enums.SaleStatus.CANCELLED);sale.setCancelledAt(at);sale.setCancellationReason(r.reason());finance.create(Enums.TransactionType.EXPENSE,Enums.TransactionSource.REVERSAL,sale.getId(),"Estorno da venda #"+sale.getId(),sale.getTotal(),at);return ViewMapper.sale(sale);}
 @Transactional public PurchaseView purchase(PurchaseInput r){Instant at=r.purchasedAt()==null?Instant.now():r.purchasedAt();String accessKey=cleanAccessKey(r.receiptAccessKey());if(accessKey!=null&&purchases.existsByReceiptAccessKey(accessKey))throw new BusinessException("Esta nota fiscal já foi importada");Purchase p=new Purchase();p.setEstablishment(r.establishment());p.setPurchasedAt(at);p.setObservations(r.observations());p.setReceiptAccessKey(accessKey);p.setTotal(BigDecimal.ZERO);purchases.save(p);BigDecimal total=BigDecimal.ZERO;for(PurchaseLine line:r.items()){PurchaseItem item=new PurchaseItem();item.setPurchase(p);item.setItemType(line.type());item.setReferenceId(line.referenceId());BigDecimal baseQuantity;BigDecimal subtotal=line.unitCost().multiply(line.quantity());if(line.type()==Enums.ItemType.PRODUCT){Product product=inventory.lockProduct(line.referenceId());baseQuantity=units.convert(line.quantity(),line.unit(),product.getUnit());inventory.add(product,baseQuantity,Enums.MovementReason.PURCHASE,p.getId(),"Compra em "+r.establishment(),at);product.setPurchasePrice(subtotal.divide(baseQuantity,2,RoundingMode.HALF_UP));item.setItemName(product.getName());}else if(line.type()==Enums.ItemType.MATERIAL){Material material=inventory.lockMaterial(line.referenceId());baseQuantity=units.convert(line.quantity(),line.unit(),material.getUnit());inventory.add(material,baseQuantity,Enums.MovementReason.PURCHASE,p.getId(),"Compra em "+r.establishment(),at);material.setUnitCost(subtotal.divide(baseQuantity,2,RoundingMode.HALF_UP));item.setItemName(material.getName());}else throw new BusinessException("Compra aceita apenas produto ou material");item.setQuantity(baseQuantity);item.setUnitCost(subtotal.divide(baseQuantity,2,RoundingMode.HALF_UP));item.setSubtotal(subtotal);p.getItems().add(item);total=total.add(subtotal);}p.setTotal(total);purchases.save(p);finance.create(Enums.TransactionType.EXPENSE,Enums.TransactionSource.PURCHASE,p.getId(),"Compra #"+p.getId()+" - "+p.getEstablishment(),total,at);return ViewMapper.purchase(p);}
 @Transactional public ExpenseView expense(ExpenseInput r){Expense e=new Expense();e.setDescription(r.description());e.setCategory(r.category());e.setOccurredAt(r.occurredAt()==null?Instant.now():r.occurredAt());e.setAmount(r.amount());e.setObservations(r.observations());expenses.save(e);finance.create(Enums.TransactionType.EXPENSE,Enums.TransactionSource.EXPENSE,e.getId(),e.getDescription(),e.getAmount(),e.getOccurredAt());return ViewMapper.expense(e);}
 @Transactional(readOnly=true) public List<SaleView> sales(){Instant cutoff=history.cutoff(Enums.HistoryType.SALES);return sales.findAllByOrderBySoldAtDesc().stream().filter(item->history.visibleAfter(item,cutoff)).map(ViewMapper::sale).toList();}@Transactional(readOnly=true) public List<PurchaseView> purchases(){Instant cutoff=history.cutoff(Enums.HistoryType.PURCHASES);return purchases.findAllByOrderByPurchasedAtDesc().stream().filter(item->history.visibleAfter(item,cutoff)).map(ViewMapper::purchase).toList();}@Transactional(readOnly=true) public List<ExpenseView> expenses(){Instant cutoff=history.cutoff(Enums.HistoryType.EXPENSES);return expenses.findAllByOrderByOccurredAtDesc().stream().filter(item->history.visibleAfter(item,cutoff)).map(ViewMapper::expense).toList();}
 private void active(boolean value,String type,String name){if(!value)throw new BusinessException(type+" inativo: "+name);} private void integer(BigDecimal value,String message){if(value.stripTrailingZeros().scale()>0)throw new BusinessException(message);}
 private String cleanAccessKey(String value){if(value==null||value.isBlank())return null;String digits=value.replaceAll("\\D","");return digits.isBlank()?null:digits;}
}
